import { readFileSync } from "node:fs";
import { expect, test } from "@playwright/test";
import { clickPin, waitForCardOpen, waitForMap } from "./helpers";

// Generated by scripts/build-metro.mjs (pretest) from content/metro/stations.json.
const metro = JSON.parse(readFileSync("app/metro/metro.public.json", "utf8")) as {
  stations: { id: string; slug?: string; name: string }[];
  stores: { stationId: string }[];
};
const noShop = metro.stations.filter((s) => !metro.stores.some((x) => x.stationId === s.id));

test("F-5 content stations without hero shops exist (regression guard for the list[0] crash)", () => {
  expect(noShop.length).toBeGreaterThan(0);
  for (const s of noShop) expect(s.slug, s.id).toBeTruthy();
});

for (const s of noShop) {
  test(`F-5 ${s.id}: marker opens a non-blank card that links to /metro/${s.slug}`, async ({ page }) => {
    const errors: string[] = [];
    page.on("pageerror", (e) => errors.push(e.message));
    await page.goto("/?reduce=1");
    await waitForMap(page);
    await clickPin(page, s.id); // real marker click, not the select() API
    await waitForCardOpen(page);
    await expect(page.locator("#card .soonbody")).not.toBeEmpty();
    await expect(page.locator("#cardTitle")).toContainText(s.name);
    const link = page.getByTestId(`metro-food-link-${s.id}`);
    await expect(link).toBeVisible();
    await expect(link).toHaveAttribute("href", `/metro/${s.slug}`);
    const [resp] = await Promise.all([
      page.waitForResponse((r) => new URL(r.url()).pathname === `/metro/${s.slug}` && r.request().resourceType() === "document"),
      link.click(),
    ]);
    expect(resp.status()).toBe(200);
    await expect(page).toHaveURL(new RegExp(`/metro/${s.slug}$`));
    expect(errors).toEqual([]);
  });
}
